<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
class GoodsReceiptItem extends Model { use HasUuids; protected $table = 'goods_receipt_items'; protected $fillable = ['tenant_id', 'goods_receipt_id', 'purchase_order_item_id', 'location_id', 'quantity', 'accepted_quantity', 'rejected_quantity', 'damaged_quantity', 'inspection_status', 'inspection_notes', 'rejection_reason', 'damage_reason', 'batch_number', 'serial_number', 'manufacturing_date', 'expiry_date']; protected function casts(): array { return ['quantity' => 'decimal:6', 'accepted_quantity' => 'decimal:6', 'rejected_quantity' => 'decimal:6', 'damaged_quantity' => 'decimal:6', 'manufacturing_date' => 'date', 'expiry_date' => 'date']; } public function receipt() { return $this->belongsTo(GoodsReceipt::class, 'goods_receipt_id'); } public function purchaseOrderItem() { return $this->belongsTo(PurchaseOrderItem::class); } public function location() { return $this->belongsTo(WarehouseLocation::class); } }
